/* Independent literal cases: expected results below are not generated by the manual helper. */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const Module = require('node:module');
const ts = require('typescript');
require.extensions['.ts'] = (loaded, filename) => loaded._compile(ts.transpileModule(fs.readFileSync(filename, 'utf8'), { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022, esModuleInterop: true } }).outputText, filename);

const originalFetch = global.fetch, originalLoad = Module._load;
const originalLocalStorage = Object.getOwnPropertyDescriptor(global, 'localStorage');
const originalSessionStorage = Object.getOwnPropertyDescriptor(global, 'sessionStorage');
let sideEffects = 0, groups = 0, literalCases = 0;
const failures = [];
const deny = name => { sideEffects++; throw Error(`Independent manual evaluation attempted ${name}`); };
global.fetch = () => deny('fetch');
Object.defineProperty(global, 'localStorage', { configurable: true, get: () => deny('localStorage') });
Object.defineProperty(global, 'sessionStorage', { configurable: true, get: () => deny('sessionStorage') });
Module._load = function (request, parent, isMain) {
  if (/^(?:node:)?(?:https?|net|tls)$/.test(request) || /(?:^|\/)(?:records|storage|auth|supabase[^/]*|result-email(?:-(?:config|transport|request))?|nango|crm)(?:\.[cm]?[jt]s)?$/.test(request)) deny(`server/provider module ${request}`);
  return originalLoad.call(this, request, parent, isMain);
};

const { FormSchema } = require('../lib/schema.ts');
const { evaluateJourneyCase, simulateJourneys } = require('../lib/journey-testing.ts');
const fixtures = require('../lib/journey-fixtures.ts');
const transfer = require('../lib/journey-fixture-transfer.ts');
const clone = value => structuredClone(value);
const check = (name, run) => {
  try { run(); groups++; console.log('PASS ' + name); }
  catch (error) { failures.push(name); console.error('FAIL ' + name + '\n' + error.stack); }
};
const form = (id, patch) => FormSchema.parse({ id, title: 'Synthetic manual case', mode: 'form', questions: [], ...patch });
const choice = (id, patch = {}) => ({ id, title: id, type: 'multiple_choice', required: true, options: ['high', 'zero', 'neutral'].map(id => ({ id, label: id })), ...patch });
const typed = (type, value) => ({ type, value });
const expected = (questionIds, patch = {}) => ({ status: 'completed', resultId: null, score: null, questionIds, categories: [], resultSectionIds: [], ...patch });
const actualFields = actual => ({ status: actual.status, resultId: actual.resultId ?? null, score: actual.score ?? null, questionIds: actual.questionIds, categories: actual.categories || [], resultSectionIds: actual.resultSectionIds || [] });
const assertActual = (actual, literal) => { assert.deepEqual(actualFields(actual), literal); literalCases++; };
const literalFixture = (value, id, answers, typedAnswers, literal) => ({ id, name: id, answers: clone(answers), ...(Object.keys(typedAnswers).length ? { inputVersion: 2, typedAnswers: clone(typedAnswers) } : {}), expected: clone(literal), createdAt: '2026-10-12T12:00:00.000Z', draftFingerprint: fixtures.journeyDraftFingerprint(value), revision: value.revision ?? null });

const threshold = form('independent-threshold', {
  questions: [{ id: 'amount', title: 'Synthetic amount', type: 'number', required: true, minVal: 0, maxVal: 20, stepVal: 2 }, choice('detail'), { id: 'note', title: 'Synthetic note', type: 'short_answer', required: true }],
  logicRules: [{ id: 'above-ten', sourceQuestionId: 'amount', operator: 'greater_than', value: '10', action: 'show_question', targetQuestionId: 'detail' }],
});
const thresholds = [
  { number: '9.999', ids: ['amount', 'note'] },
  { number: '10', ids: ['amount', 'note'] },
  { number: '10.001', ids: ['amount', 'detail', 'note'] },
  { number: '0', ids: ['amount', 'note'] },
  { number: '20', ids: ['amount', 'detail', 'note'] },
];
const keyed = form('independent-keyed', {
  mode: 'quiz', questions: [{ id: 'number', title: 'Synthetic keyed number', type: 'number', required: true, minVal: -2, maxVal: 2, points: 10, correctAnswerText: '1' }, { id: 'word', title: 'Synthetic keyed word', type: 'short_answer', required: true, points: 10, correctAnswerText: 'calm' }],
  outcomeTiers: [{ id: 'complete', title: 'Complete', message: '', badge: '', minScorePercent: 100, maxScorePercent: 100 }, { id: 'partial', title: 'Partial', message: '', badge: '', minScorePercent: 1, maxScorePercent: 99 }, { id: 'zero', title: 'Zero', message: '', badge: '', minScorePercent: 0, maxScorePercent: 0 }],
});
const keyedCases = [
  { number: '1', word: '  CaLm  ', score: 100, resultId: 'complete' },
  { number: '1.0', word: 'calm', score: 50, resultId: 'partial' },
  { number: '01', word: 'calm', score: 50, resultId: 'partial' },
  { number: '1e0', word: 'calm', score: 50, resultId: 'partial' },
  { number: '0', word: 'other', score: 0, resultId: 'zero' },
  { number: '-1', word: 'CALM', score: 50, resultId: 'partial' },
];
const textBranch = form('independent-text-branch', {
  questions: [{ id: 'word', title: 'Synthetic text route', type: 'short_answer' }, choice('equal'), choice('contains'), choice('different'), choice('finish')],
  logicRules: [
    { id: 'exact', sourceQuestionId: 'word', operator: 'equals', value: 'calm', action: 'show_question', targetQuestionId: 'equal' },
    { id: 'part', sourceQuestionId: 'word', operator: 'contains', value: 'calm', action: 'show_question', targetQuestionId: 'contains' },
    { id: 'other', sourceQuestionId: 'word', operator: 'not_equals', value: 'calm', action: 'show_question', targetQuestionId: 'different' },
  ],
});
const textCases = [
  { text: '  CaLm  ', ids: ['word', 'equal', 'contains', 'finish'] },
  { text: 'very CALM today', ids: ['word', 'contains', 'different', 'finish'] },
  { text: 'other', ids: ['word', 'different', 'finish'] },
  { text: '', ids: ['word', 'finish'] },
];
const scorecard = form('independent-scorecard', {
  questions: [{ id: 'amount', title: 'Synthetic routing amount', type: 'number', required: true }, choice('alpha'), choice('beta')],
  logicRules: [{ id: 'second-area', sourceQuestionId: 'amount', operator: 'greater_than', value: '10', action: 'show_question', targetQuestionId: 'beta' }],
  marketing: {
    kind: 'scorecard', categories: [{ id: 'a', title: 'A', minAnswers: 1 }, { id: 'b', title: 'B', minAnswers: 1 }],
    scorecard: { title: 'Synthetic scorecard', bands: [{ id: 'low', title: 'Low', min: 0, max: 49 }, { id: 'high', title: 'High', min: 50, max: 100 }] },
    rules: ['alpha', 'beta'].flatMap((questionId, index) => ['high', 'zero'].map((answerId, pointsIndex) => ({ id: `${questionId}-${answerId}`, questionId, answerId, targetId: index ? 'b' : 'a', points: pointsIndex ? 0 : 10, effect: 'add' }))),
    resultSections: [
      { id: 'intro', type: 'text', title: 'Introduction' },
      { id: 'a-zero', type: 'text', title: 'A zero', condition: { type: 'score', categoryId: 'a', min: 0, max: 0 } },
      { id: 'b-high', type: 'text', title: 'B high', condition: { type: 'score', categoryId: 'b', min: 100, max: 100 } },
      { id: 'finish', type: 'text', title: 'Finish' },
    ],
  },
});
const cat = (id, score, answered, applicable = 1, minAnswers = 1) => ({ id, score, answered, applicable, minAnswers });
const scoreCases = [
  { number: '10', a: 'high', b: 'high', literal: expected(['amount', 'alpha'], { status: 'scored', categories: [cat('a', 100, 1), cat('b', null, 0, 0)], resultSectionIds: ['intro', 'finish'] }) },
  { number: '11', a: 'neutral', b: 'high', literal: expected(['amount', 'alpha', 'beta'], { status: 'scored', categories: [cat('a', null, 0), cat('b', 100, 1)], resultSectionIds: ['intro', 'b-high', 'finish'] }) },
  { number: '11', a: 'zero', b: 'high', literal: expected(['amount', 'alpha', 'beta'], { status: 'scored', score: 50, resultId: 'high', categories: [cat('a', 0, 1), cat('b', 100, 1)], resultSectionIds: ['intro', 'a-zero', 'b-high', 'finish'] }) },
  { number: '11', a: 'high', b: 'zero', literal: expected(['amount', 'alpha', 'beta'], { status: 'scored', score: 50, resultId: 'high', categories: [cat('a', 100, 1), cat('b', 0, 1)], resultSectionIds: ['intro', 'finish'] }) },
  { number: '11', a: 'zero', b: 'zero', literal: expected(['amount', 'alpha', 'beta'], { status: 'scored', score: 0, resultId: 'low', categories: [cat('a', 0, 1), cat('b', 0, 1)], resultSectionIds: ['intro', 'a-zero', 'finish'] }) },
  { number: '11', a: 'neutral', b: 'neutral', literal: expected(['amount', 'alpha', 'beta'], { status: 'no_match', categories: [cat('a', null, 0), cat('b', null, 0)], resultSectionIds: ['intro', 'finish'] }) },
];

try {
  check('literal number thresholds, inclusive bounds and skipped supplied answers follow the actual evaluator', () => {
    for (const item of thresholds) {
      const actual = evaluateJourneyCase(threshold, { amount: item.number, detail: 'high', note: 'synthetic' });
      assertActual(actual, expected(item.ids));
      assert.equal(Object.hasOwn(actual.answers, 'detail'), item.ids.includes('detail'));
    }
    for (const amount of ['-0.001', '20.001']) assert.equal(evaluateJourneyCase(threshold, { amount, detail: 'high', note: 'synthetic' }).status, 'invalid');
    assert.equal(evaluateJourneyCase(threshold, { amount: '10.001', detail: 'high', note: 'synthetic' }).status, 'completed', 'step=2 does not become a new runtime scoring restriction');
  });
  check('literal keyed number lexemes and case/outer-whitespace text scores are preserved', () => {
    for (const item of keyedCases) assertActual(evaluateJourneyCase(keyed, { number: item.number, word: item.word }), expected(['number', 'word'], { status: 'scored', score: item.score, resultId: item.resultId }));
  });
  check('literal equals/contains/not-equals text routes distinguish unanswered values', () => {
    for (const item of textCases) assertActual(evaluateJourneyCase(textBranch, { word: item.text, equal: 'high', contains: 'high', different: 'high', finish: 'high' }), expected(item.ids));
  });
  check('literal scorecards distinguish absent coverage, unknown answers, mapped zero, paired categories and ordered sections', () => {
    for (const item of scoreCases) assertActual(evaluateJourneyCase(scorecard, { amount: item.number, alpha: item.a, beta: item.b }), item.literal);
    const minimum = clone(scorecard); minimum.marketing.categories[0].minAnswers = 2;
    assertActual(evaluateJourneyCase(minimum, { amount: '11', alpha: 'high', beta: 'zero' }), expected(['amount', 'alpha', 'beta'], { status: 'scored', categories: [cat('a', null, 1, 1, 2), cat('b', 0, 1)], resultSectionIds: ['intro', 'finish'] }));
  });
  check('manual domains do not turn bounded automatic simulation into exhaustive coverage', () => {
    const before = JSON.stringify(threshold), result = simulateJourneys(threshold, 8);
    assert.equal(result.exhaustive, false); assert.equal(result.totalCombinations, null);
    assert.ok(result.unsupportedQuestionIds.includes('amount')); assert.ok(result.cases.length <= 8);
    assert.equal(JSON.stringify(threshold), before);
  });

  const manual = require('../lib/manual-journey.ts');
  const prepare = (value, input, id = 'manual-case', raw = null, name = id) => manual.prepareManualJourneyCase(value, input, name, id, raw);
  const apply = (value, input, review, raw = review.libraryRaw, name = review.name) => manual.applyManualJourneyCase(value, input, name, raw, review);
  const keyedInput = { answers: {}, typedAnswers: { number: typed('number', '1.0'), word: typed('short_answer', '  CaLm  ') } };
  const finiteForm = form('independent-finite', { questions: [choice('one')] });
  const legacy = literalFixture(finiteForm, 'legacy', { one: 'high' }, {}, expected(['one']));
  delete legacy.expected.categories; delete legacy.expected.resultSectionIds;
  const versionOneRaw = JSON.stringify({ version: 1, quizId: finiteForm.id, cases: [legacy] });
  const bundle = (quizId, cases, version = 2) => JSON.stringify({ format: 'pippi-journey-cases', version, quizId, cases });

  check('review and saved rerun retain literal threshold expectations while pruning only skipped inputs', () => {
    for (const item of thresholds) {
      const input = { answers: { detail: 'high' }, typedAnswers: { amount: typed('number', item.number), note: typed('short_answer', 'synthetic') } };
      const before = JSON.stringify(input), review = prepare(threshold, input, 'threshold-' + item.number.replace('.', '-'));
      assertActual(review.actual, expected(item.ids)); assert.deepEqual(review.fixture.expected, expected(item.ids));
      assert.deepEqual(review.omittedQuestionIds, item.ids.includes('detail') ? [] : ['detail']);
      const saved = apply(threshold, input, review);
      assert.equal(saved.fixture.inputVersion, 2); assert.equal(saved.fixture.typedAnswers.amount.value, item.number);
      assert.equal(Object.hasOwn(saved.fixture.answers, 'detail'), item.ids.includes('detail'));
      assert.deepEqual(fixtures.parseJourneyFixtures(saved.serialized, threshold.id), saved.cases);
      assert.equal(fixtures.runJourneyFixture(threshold, saved.fixture).passed, true);
      assertActual(fixtures.runJourneyFixture(threshold, saved.fixture).actual, expected(item.ids));
      assert.equal(JSON.stringify(input), before, 'review and path pruning do not mutate volatile inputs');
    }
  });
  check('manual helper and rerun agree with independent lexical grade and text-route literals', () => {
    for (const [index, item] of keyedCases.entries()) {
      const input = { answers: {}, typedAnswers: { number: typed('number', item.number), word: typed('short_answer', item.word) } };
      const literal = expected(['number', 'word'], { status: 'scored', score: item.score, resultId: item.resultId });
      const review = prepare(keyed, input, 'keyed-' + index);
      assertActual(review.actual, literal); assert.deepEqual(review.fixture.expected, literal);
      const saved = apply(keyed, input, review).fixture;
      assert.equal(saved.typedAnswers.number.value, item.number); assert.equal(saved.typedAnswers.word.value, item.word);
      assertActual(fixtures.runJourneyFixture(keyed, saved).actual, literal);
    }
    for (const [index, item] of textCases.entries()) {
      const input = { answers: { equal: 'high', contains: 'high', different: 'high', finish: 'high' }, typedAnswers: item.text ? { word: typed('short_answer', item.text) } : {} };
      const review = prepare(textBranch, input, 'text-' + index), saved = apply(textBranch, input, review).fixture;
      assertActual(review.actual, expected(item.ids)); assert.deepEqual(saved.expected, expected(item.ids));
      assert.equal(fixtures.runJourneyFixture(textBranch, saved).passed, true);
    }
  });
  check('manual routing preserves first matching jump, hide precedence and explicit ending semantics', () => {
    const jump = form('independent-jump', {
      questions: [{ id: 'n', title: 'Synthetic', type: 'number', required: true }, choice('skipped'), choice('first'), choice('last')],
      logicRules: [
        { id: 'first-match', sourceQuestionId: 'n', operator: 'greater_than', value: '0', action: 'jump_to_question', targetQuestionId: 'first' },
        { id: 'also-matches', sourceQuestionId: 'n', operator: 'greater_than', value: '-1', action: 'jump_to_question', targetQuestionId: 'last' },
        { id: 'show-last', sourceQuestionId: 'n', operator: 'greater_than', value: '0', action: 'show_question', targetQuestionId: 'last' },
        { id: 'hide-last', sourceQuestionId: 'n', operator: 'greater_than', value: '0', action: 'hide_question', targetQuestionId: 'last' },
      ],
    });
    const input = { answers: { skipped: 'high', first: 'zero', last: 'high' }, typedAnswers: { n: typed('number', '1') } };
    const review = prepare(jump, input, 'first-rule');
    assertActual(review.actual, expected(['n', 'first']));
    assert.deepEqual(review.fixture.answers, { first: 'zero' }); assert.deepEqual(review.omittedQuestionIds, ['skipped', 'last']);
    const ending = form('independent-ending', {
      questions: [{ id: 'word', title: 'Synthetic', type: 'short_answer', required: true }, { id: 'contact', title: 'Unsupported contact', type: 'email', required: true }],
      outcomeTiers: [{ id: 'done', title: 'Done', message: '', badge: '', minScorePercent: 0, maxScorePercent: 100 }],
      logicRules: [{ id: 'finish-early', sourceQuestionId: 'word', operator: 'equals', value: 'stop', action: 'jump_to_ending', targetOutcomeTierId: 'done' }],
    });
    const endInput = { answers: {}, typedAnswers: { word: typed('short_answer', ' STOP ') } };
    const endReview = prepare(ending, endInput, 'early-stop');
    assertActual(endReview.actual, expected(['word'], { resultId: 'done' }));
    assert.equal(fixtures.runJourneyFixture(ending, apply(ending, endInput, endReview).fixture).passed, true);
  });
  check('manual scorecard cases preserve literal category coverage/null and ordered sections', () => {
    for (const [index, item] of scoreCases.entries()) {
      const input = { answers: { alpha: item.a, beta: item.b }, typedAnswers: { amount: typed('number', item.number) } };
      const review = prepare(scorecard, input, 'scorecard-' + index), saved = apply(scorecard, input, review).fixture;
      assertActual(review.actual, item.literal); assert.deepEqual(saved.expected, item.literal);
      assert.equal(fixtures.runJourneyFixture(scorecard, saved).passed, true);
      assertActual(fixtures.runJourneyFixture(scorecard, saved).actual, item.literal);
    }
    const paired = literalFixture(scorecard, 'paired', { alpha: 'zero', beta: 'high' }, { amount: typed('number', '11') }, scoreCases[2].literal);
    const changed = clone(scorecard);
    changed.marketing.rules.find(rule => rule.id === 'alpha-zero').points = 10;
    changed.marketing.rules.find(rule => rule.id === 'beta-high').points = 0;
    changed.marketing.rules.push({ id: 'beta-positive-maximum', questionId: 'beta', answerId: 'neutral', targetId: 'b', points: 10, effect: 'add' });
    const actual = fixtures.runJourneyFixture(changed, paired);
    assert.equal(actual.actual.score, 50); assert.equal(actual.passed, false);
    assert.ok(actual.differences.some(value => value.includes('Category “a” score: expected 0%, received 100%')));
    assert.ok(actual.differences.some(value => value.includes('Category “b” score: expected 100%, received 0%')));
    assert.ok(actual.differences.some(value => value.startsWith('Result sections in order:')));
  });
  check('explicit review cancellation is inert; changed draft/input/name/raw library and tampering cannot save', () => {
    const value = clone(keyed), input = clone(keyedInput), beforeForm = JSON.stringify(value), beforeInput = JSON.stringify(input);
    const review = prepare(value, input, 'reviewed'), beforeReview = JSON.stringify(review);
    assert.equal(JSON.stringify(value), beforeForm); assert.equal(JSON.stringify(input), beforeInput);
    assert.equal(sideEffects, 0, 'preparing then discarding review never persists it');
    assert.throws(() => apply({ ...value, title: 'Changed while reviewing' }, input, review));
    assert.throws(() => apply(value, { ...input, typedAnswers: { ...input.typedAnswers, number: typed('number', '1') } }, review));
    assert.throws(() => apply(value, input, review, null, 'Changed name'));
    assert.throws(() => apply(value, input, review, JSON.stringify({ version: 1, quizId: value.id, cases: [] })));
    const tampered = clone(review); tampered.fixture.expected.score = 100;
    assert.throws(() => apply(value, input, tampered));
    const tamperedInput = clone(review); tamperedInput.fixture.typedAnswers.number.value = '1';
    assert.throws(() => apply(value, input, tamperedInput));
    const foreign = clone(value); foreign.id = 'other-quiz'; assert.throws(() => apply(foreign, input, review));
    assert.equal(JSON.stringify(review), beforeReview); assert.equal(JSON.stringify(value), beforeForm); assert.equal(JSON.stringify(input), beforeInput);
    const saved = apply(value, input, review);
    assert.deepEqual(saved.fixture.expected, expected(['number', 'word'], { status: 'scored', score: 50, resultId: 'partial' }));
    assert.throws(() => apply(value, input, review, saved.serialized), 'replay with a newer raw library is rejected');
  });
  check('numeric and text representation limits reject coercion/control payloads without changing valid lexemes', () => {
    const numberOnly = form('number-only', { questions: [{ id: 'n', title: 'Synthetic', type: 'number', required: true }] });
    for (const value of ['0', '-0', '+1', '.5', '1.', '1e-3', '-2.5E+2']) {
      const input = { answers: {}, typedAnswers: { n: typed('number', value) } }, review = prepare(numberOnly, input, 'valid-number');
      assert.equal(apply(numberOnly, input, review).fixture.typedAnswers.n.value, value);
    }
    for (const value of [0, null, {}, [], '0x10', 'Infinity', '-Infinity', 'NaN', '1e', '--1', '1,000', '1'.repeat(65), '1e999', '\n1']) {
      assert.throws(() => prepare(numberOnly, { answers: {}, typedAnswers: { n: typed('number', value) } }), String(value));
    }
    const textOnly = form('text-only', { questions: [{ id: 't', title: 'Synthetic', type: 'short_answer', required: true }] });
    for (const value of ['界'.repeat(256), 'é synthetic 🧪', '  intentional spaces  ']) {
      const input = { answers: {}, typedAnswers: { t: typed('short_answer', value) } }, review = prepare(textOnly, input, 'valid-text');
      assert.equal(apply(textOnly, input, review).fixture.typedAnswers.t.value, value);
    }
    for (const value of [3, null, {}, [], 'x'.repeat(257), 'line\nbreak', 'tab\there', 'a\u0000b', 'a\u007fb', 'a\u202eb', 'a\u2066b', '\ud800', '\udfff']) assert.throws(() => prepare(textOnly, { answers: {}, typedAnswers: { t: typed('short_answer', value) } }));
  });
  check('both maps reject unsupported provenance even when an input would be skipped', () => {
    const baseInput = { answers: { detail: 'high' }, typedAnswers: { amount: typed('number', '10'), note: typed('short_answer', 'synthetic') } };
    const changes = [
      input => { input.answers.amount = '10'; },
      input => { input.typedAnswers.detail = typed('short_answer', 'high'); },
      input => { input.typedAnswers.note.type = 'number'; },
      input => { input.answers.detail = 'missing'; },
      input => { input.answers.detail = ['high']; },
      input => { input.answers.detail = true; },
      input => { input.typedAnswers.missing = typed('short_answer', 'synthetic'); },
      input => { input.typedAnswers.amount.extra = 'unknown'; },
      input => { input.extra = true; },
    ];
    for (const mutate of changes) { const input = clone(baseInput); mutate(input); assert.throws(() => prepare(threshold, input)); }
    const duplicate = clone(threshold); duplicate.questions.push(clone(duplicate.questions[1])); assert.throws(() => prepare(duplicate, baseInput));
    const multi = form('independent-multi', { questions: [choice('multi', { type: 'multiselect' }), { id: 'n', title: 'Synthetic', type: 'number', required: true }] });
    assert.throws(() => prepare(multi, { answers: { multi: ['high', 'high'] }, typedAnswers: { n: typed('number', '1') } }));
    for (const type of ['email', 'password', 'file_upload', 'captcha', 'paragraph', 'currency']) {
      const forbidden = form('unsupported-' + type, { questions: [{ id: 'unsafe', title: 'Unsupported synthetic field', type }, { id: 'n', title: 'Synthetic', type: 'number', required: true }] });
      assert.throws(() => prepare(forbidden, { answers: { unsafe: 'high' }, typedAnswers: { n: typed('number', '1') } }));
      assert.throws(() => prepare(forbidden, { answers: {}, typedAnswers: { unsafe: typed('short_answer', 'synthetic'), n: typed('number', '1') } }));
    }
    for (const reserved of ['__proto__', 'constructor', 'prototype']) for (const map of ['answers', 'typedAnswers']) {
      const input = clone(baseInput); Object.defineProperty(input[map], reserved, { value: map === 'answers' ? 'high' : typed('short_answer', 'synthetic'), enumerable: true });
      assert.throws(() => prepare(threshold, input), `Reject own reserved ${map} key ${reserved}`);
    }
    assert.throws(() => prepare(threshold, { answers: {}, typedAnswers: Object.fromEntries(Array.from({ length: 201 }, (_, index) => ['n' + index, typed('number', '1')])) }));
  });
  check('required unsupported fields block review; optional omission stays explicit and blank numeric input never becomes zero', () => {
    for (const type of ['email', 'password', 'file_upload', 'captcha']) {
      const required = form('required-' + type, { questions: [{ id: 'n', title: 'Synthetic', type: 'number', required: true }, { id: 'unsafe', title: 'Unsupported', type, required: true }] });
      const input = { answers: {}, typedAnswers: { n: typed('number', '1') } };
      assert.throws(() => prepare(required, input));
      if (type !== 'captcha') {
        const optional = clone(required); optional.questions[1].required = false;
        const review = prepare(optional, input, 'optional');
        assert.ok(review.unsupportedQuestionIds.includes('unsafe')); assert.equal(Object.hasOwn(review.fixture.answers, 'unsafe'), false); assert.equal(Object.hasOwn(review.fixture.typedAnswers, 'unsafe'), false);
      }
    }
    const blank = form('optional-blank', { questions: [{ id: 'n', title: 'Synthetic', type: 'number' }, choice('one')] });
    const input = { answers: { one: 'high' }, typedAnswers: { n: typed('number', '   ') } };
    const review = prepare(blank, input, 'blank-number');
    assertActual(review.actual, expected(['n', 'one']));
    assert.equal(Object.hasOwn(review.actual.answers, 'n'), false); assert.equal(Object.hasOwn(review.fixture, 'typedAnswers'), false);
    const requiredBlank = clone(blank); requiredBlank.questions[0].required = true; assert.throws(() => prepare(requiredBlank, input));
  });
  check('saved v2 reruns validate both maps against current exact types/options rather than reinterpret values', () => {
    const input = { answers: { detail: 'high' }, typedAnswers: { amount: typed('number', '11'), note: typed('short_answer', 'synthetic') } };
    const saved = apply(threshold, input, prepare(threshold, input, 'provenance')).fixture;
    for (const mutate of [
      value => { value.questions[0].type = 'short_answer'; },
      value => { value.questions[2].type = 'number'; },
      value => { value.questions[1].type = 'short_answer'; delete value.questions[1].options; },
      value => { value.questions[1].options = value.questions[1].options.filter(option => option.id !== 'high'); },
      value => { value.questions.splice(2, 1); },
    ]) {
      const changed = clone(threshold); mutate(changed);
      const result = fixtures.runJourneyFixture(changed, saved);
      assert.equal(result.passed, false); assert.equal(result.actual.status, 'invalid'); assert.ok(result.differences.length);
    }
    const renamed = clone(threshold); renamed.questions[1].options[0].label = 'Renamed option, same ID';
    assert.equal(fixtures.runJourneyFixture(renamed, saved).passed, true); assert.equal(fixtures.runJourneyFixture(renamed, saved).draftChanged, true);
    const corrupted = clone(saved); corrupted.answers.detail = ['high', 'high'];
    assert.equal(fixtures.runJourneyFixture(threshold, corrupted).passed, false);
    const withoutTyped = clone(saved); delete withoutTyped.typedAnswers;
    assert.equal(fixtures.runJourneyFixture(threshold, withoutTyped).passed, false);
  });
  check('legacy local reads preserve noncanonical metadata/unknown fields/duplicates; strict promotion cannot rewrite them', () => {
    assert.deepEqual(fixtures.parseJourneyFixtures(versionOneRaw, finiteForm.id), [legacy]);
    assert.equal(Object.hasOwn(fixtures.parseJourneyFixtures(versionOneRaw, finiteForm.id)[0].expected, 'categories'), false);
    const promotedForm = clone(finiteForm); promotedForm.questions.push({ id: 'n', title: 'Synthetic', type: 'number', required: true });
    const input = { answers: { one: 'high' }, typedAnswers: { n: typed('number', '1') } };
    for (const mutate of [
      item => { item.createdAt = 'yesterday'; },
      item => { item.draftFingerprint = 'historical'; },
      item => { item.extra = { preserved: true }; },
      item => { item.answers.one = ['high', 'high']; },
    ]) {
      const item = clone(legacy); mutate(item);
      const raw = JSON.stringify({ version: 1, quizId: finiteForm.id, cases: [item] });
      assert.deepEqual(fixtures.parseJourneyFixtures(raw, finiteForm.id), [item]);
      assert.throws(() => prepare(promotedForm, input, 'new-manual', raw));
      assert.deepEqual(JSON.parse(raw).cases, [item]);
    }
    const review = prepare(promotedForm, input, 'new-manual', versionOneRaw), result = apply(promotedForm, input, review);
    assert.deepEqual(result.cases[0], legacy); assert.equal(JSON.parse(result.serialized).version, 2);
    assert.equal(Object.hasOwn(result.cases[0].expected, 'categories'), false, 'promotion must not expand old assertions');
  });
  check('version1 rejects reserved manual markers at envelope/case boundaries; v2 rejects malformed nested shapes', () => {
    for (const target of ['envelope', 'case']) for (const marker of ['inputVersion', 'typedAnswers']) {
      const local = JSON.parse(versionOneRaw); (target === 'envelope' ? local : local.cases[0])[marker] = marker === 'inputVersion' ? 2 : { n: typed('number', '1') };
      assert.throws(() => fixtures.parseJourneyFixtures(JSON.stringify(local), finiteForm.id));
      assert.throws(() => transfer.prepareJourneyFixtureImport(finiteForm, JSON.stringify({ ...local, format: 'pippi-journey-cases' }), []));
    }
    const valid = apply(keyed, keyedInput, prepare(keyed, keyedInput, 'strict-manual')).fixture;
    for (const mutate of [
      item => { item.inputVersion = 3; },
      item => { item.typedAnswers = {}; },
      item => { item.typedAnswers.number.type = 'currency'; },
      item => { item.typedAnswers.number.value = 1; },
      item => { item.typedAnswers.word.value = 'x\ny'; },
      item => { item.typedAnswers.word.unknown = true; },
      item => { item.answers.number = 'high'; },
      item => { item.answers.other = ['high', 'high']; },
      item => { item.unexpected = true; },
    ]) {
      const item = clone(valid); mutate(item);
      assert.throws(() => fixtures.parseJourneyFixtures(JSON.stringify({ version: 2, quizId: keyed.id, cases: [item] }), keyed.id));
      assert.throws(() => transfer.prepareJourneyFixtureImport(keyed, bundle(keyed.id, [item]), []));
    }
  });
  check('raw reserved keys cannot disappear during strict local/import/library validation', () => {
    const valid = literalFixture(keyed, 'reserved-map', {}, { number: typed('number', '1.0'), word: typed('short_answer', 'calm') }, expected(['number', 'word'], { status: 'scored', resultId: 'partial', score: 50 }));
    for (const map of ['answers', 'typedAnswers']) {
      const value = clone(valid); Object.defineProperty(value[map], '__proto__', { value: map === 'answers' ? 'high' : typed('short_answer', 'synthetic'), enumerable: true });
      const local = JSON.stringify({ version: 2, quizId: keyed.id, cases: [value] });
      assert.throws(() => fixtures.parseJourneyFixtures(local, keyed.id), 'Strict v2 local input must not silently strip a reserved own key');
      assert.throws(() => transfer.prepareJourneyFixtureImport(keyed, bundle(keyed.id, [value]), []), 'Strict import must not silently strip a reserved own key');
      assert.throws(() => fixtures.validateJourneyFixtureLibrary([value]), 'Strict current-library validation must inspect the raw keys');
    }
    const old = clone(legacy); Object.defineProperty(old.answers, '__proto__', { value: 'high', enumerable: true });
    const legacyRaw = JSON.stringify({ version: 1, quizId: finiteForm.id, cases: [old] });
    assert.deepEqual(fixtures.parseJourneyFixtures(legacyRaw, finiteForm.id), [old], 'Do not reinterpret older accepted data on read');
    assert.throws(() => fixtures.validateJourneyFixtureLibrary([old]));
    assert.throws(() => transfer.prepareJourneyFixtureImport(finiteForm, bundle(finiteForm.id, [legacy], 1), [old]));
    assert.deepEqual(JSON.parse(legacyRaw).cases, [old]);
  });
  check('v2 imports preserve literal expectations and skipped current IDs without silently rescoring or replacing', () => {
    const saved = literalFixture(scorecard, 'literal-import', { alpha: 'zero', beta: 'high' }, { amount: typed('number', '11') }, scoreCases[2].literal);
    saved.expected.score = 17; saved.expected.resultId = 'historical-result'; saved.expected.resultSectionIds = ['finish', 'intro'];
    const text = transfer.exportJourneyFixtures(scorecard.id, [saved]); assert.equal(JSON.parse(text).version, 2);
    const review = transfer.prepareJourneyFixtureImport(scorecard, text, []), result = transfer.applyJourneyFixtureImport(scorecard, [], review);
    assert.deepEqual(result, [saved]); assert.equal(fixtures.runJourneyFixture(scorecard, result[0]).passed, false);
    const deleted = clone(scorecard); deleted.questions.splice(0, 1); deleted.logicRules = [];
    assert.deepEqual(transfer.applyJourneyFixtureImport(deleted, [], transfer.prepareJourneyFixtureImport(deleted, text, [])), [saved]);
    assert.equal(fixtures.runJourneyFixture(deleted, saved).passed, false);
    assert.throws(() => transfer.applyJourneyFixtureImport(scorecard, [{ ...saved, name: 'Newer library' }], review));
    assert.throws(() => transfer.prepareJourneyFixtureImport(scorecard, text, [{ ...saved, expected: { ...saved.expected, score: 18 } }]));
    const tampered = clone(review); tampered.cases[0].typedAnswers.amount.value = '10'; assert.throws(() => transfer.applyJourneyFixtureImport(scorecard, [], tampered));
    assert.throws(() => transfer.prepareJourneyFixtureImport({ ...scorecard, id: 'other' }, text, []));
  });
  check('combined25, exact UTF8 transfer limit and500000-character local boundary remain distinct', () => {
    const saved = apply(keyed, keyedInput, prepare(keyed, keyedInput, 'bounds')).fixture;
    const full = Array.from({ length: 25 }, (_, index) => ({ ...clone(saved), id: 'case-' + index }));
    const raw = fixtures.serializeJourneyFixtures(keyed.id, full);
    assert.equal(fixtures.parseJourneyFixtures(raw, keyed.id).length, 25);
    assert.throws(() => prepare(keyed, keyedInput, 'one-too-many', raw));
    assert.throws(() => fixtures.serializeJourneyFixtures(keyed.id, [...full, { ...saved, id: 'extra' }]));
    const text = transfer.exportJourneyFixtures(keyed.id, [saved]), maxBytes = transfer.MAX_JOURNEY_TRANSFER_BYTES;
    const exact = text + ' '.repeat(maxBytes - Buffer.byteLength(text));
    assert.equal(transfer.prepareJourneyFixtureImport(keyed, exact, []).cases.length, 1);
    assert.throws(() => transfer.prepareJourneyFixtureImport(keyed, exact + ' ', []));
    assert.throws(() => transfer.prepareJourneyFixtureImport(keyed, text + '界'.repeat(maxBytes / 2), []));
    assert.throws(() => transfer.decodeJourneyFixtureFile(Uint8Array.from([0xff, 0xfe])));
    const single = fixtures.serializeJourneyFixtures(keyed.id, [saved]);
    assert.equal(fixtures.parseJourneyFixtures(single + ' '.repeat(500000 - single.length), keyed.id).length, 1);
    assert.throws(() => fixtures.parseJourneyFixtures(single + ' '.repeat(500001 - single.length), keyed.id));
  });

  assert.equal(sideEffects, 0);
  assert.deepEqual(failures, [], 'Independent manual checks must all pass');
  console.log(`${groups} independent manual journey groups passed; ${literalCases} literal evaluator comparisons; no network/storage/provider access.`);
} finally {
  global.fetch = originalFetch; Module._load = originalLoad;
  for (const [name, descriptor] of [['localStorage', originalLocalStorage], ['sessionStorage', originalSessionStorage]]) {
    if (descriptor) Object.defineProperty(global, name, descriptor); else delete global[name];
  }
}
